(864753, 98500, 19959, '<td valign="top">Nice zoom Effect. I must try this myself sometime.</td>', 'Nice zoom Effect. I must try this myself sometime.', '2004-08-18 04:38:41.000000', NULL, 1),
(864755, 98094, 19959, '<td valign="top">Interesting effect.</td>', 'Interesting effect.', '2004-08-18 04:40:50.000000', NULL, 1),
(864758, 97873, 24511, '<td valign="top">Your photo has depth, the neon glow theme is captured with explosif movement and glare.  Even as a small thumbnail it capture my curiosity.  The variety is line sizes and direction allow me to explore but the shaded areas keeps the photo from being too busy.  Fantastic thanks!</td>', 'Your photo has depth, the neon glow theme is captured with explosif movement and glare.  Even as a small thumbnail it capture my curiosity.  The variety is line sizes and direction allow me to explore but the shaded areas keeps the photo from being too busy.  Fantastic thanks!', '2004-08-18 04:45:17.000000', NULL, 1),
(864761, 98486, 19959, '<td valign="top">Neat idea.</td>', 'Neat idea.', '2004-08-18 04:46:24.000000', NULL, 1),
(864762, 97195, 19959, '<td valign="top">Nice picture. Might have been better cropped a little tighter.</td>', 'Nice picture. Might have been better cropped a little tighter.', '2004-08-18 04:47:22.000000', NULL, 1),
(864766, 98499, 24511, '<td valign="top">I liked this photo better as a thumbnail for some reason.  The close-up has a plastic artificial flavour.  I enjoyed the glowing rays of light that seem to engulf my attention towards the middle.  At the opposite, the bright colours urge me to look around at the borders.  Great composition.  Thanks!</td>', 'I liked this photo better as a thumbnail for some reason.  The close-up has a plastic artificial flavour.  I enjoyed the glowing rays of light that seem to engulf my attention towards the middle.  At the opposite, the bright colours urge me to look around at the borders.  Great composition.  Thanks!', '2004-08-18 04:51:13.000000', NULL, 1),
(864773, 97508, 19959, '<td valign="top">Excellent... Must try this technique myself one day!</td>', 'Excellent... Must try this technique myself one day!', '2004-08-18 04:59:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(864774, 97675, 19959, '<td valign="top">Maybe more flourescent... nice photo though..</td>', 'Maybe more flourescent... nice photo though..', '2004-08-18 05:01:34.000000', NULL, 1),
(864775, 98187, 24511, '<td valign="top">The title is what made me click to your photo.  Overlapping is interresting.  I love nature yet the neon is contrasting with the sales billboard fakiness.  How unspiritual visually for a theme that is usually into soulness.  Even the shapes resembles the cartoon face of a monkey with pink ears, red eyes and blue jaw.  Weird!  Thanks for submitting.</td>', 'The title is what made me click to your photo.  Overlapping is interresting.  I love nature yet the neon is contrasting with the sales billboard fakiness.  How unspiritual visually for a theme that is usually into soulness.  Even the shapes resembles the cartoon face of a monkey with pink ears, red eyes and blue jaw.  Weird!  Thanks for submitting.', '2004-08-18 05:01:51.000000', NULL, 1),
(864780, 98124, 24511, '<td valign="top">Very beautiful architecture lines.  The Neon is very subtle.  I almost let this photo slip by.  The more I look at it, the more I am loving it.  The oval bulbs and roof lighting adds variety of light.  The main entrance attracks the eye with giant arms that seem to be crossed and pulling the two neon words towards the focal point.  Great angle of vanishing point and framing is exquisit.  Stupendous!</td>', 'Very beautiful architecture lines.  The Neon is very subtle.  I almost let this photo slip by.  The more I look at it, the more I am loving it.  The oval bulbs and roof lighting adds variety of light.  The main entrance attracks the eye with giant arms that seem to be crossed and pulling the two neon words towards the focal point.  Great angle of vanishing point and framing is exquisit.  Stupendous!', '2004-08-18 05:11:49.000000', NULL, 1),
(864783, 98109, 24511, '<td valign="top">So this is how the earth was formed...through gases, gravity and explosive changes.  Of course yours is but a model but if you consider the size of what we know exists,  this ball of techno-junk could be the known universe to zillions of specs of dust.  Who say''s you have to be a scientist to talk like one.  Thanks!</td>', 'So this is how the earth was formed...through gases, gravity and explosive changes.  Of course yours is but a model but if you consider the size of what we know exists,  this ball of techno-junk could be the known universe to zillions of specs of dust.  Who say''s you have to be a scientist to talk like one.  Thanks!', '2004-08-18 05:20:03.000000', NULL, 1),
(864789, 98094, 24459, '<td valign="top">Well done. Quick moves. Great idea</td>', 'Well done. Quick moves. Great idea', '2004-08-18 05:31:03.000000', NULL, 1),
(864791, 98055, 24511, '<td valign="top">I always enjoy reflections.  It gives me a chance to imagine and create my own story behind the true subject before me.  Of course the car brand is great but my attention is directed to the broken Y and the oval shapes being framed by the aggressive red and yellow lines above and bellow.  I love a mystery and you''ve given me one that holds my interest Sherlock.  Keeping the blue colours a mystery keeps me in love with the photo.  Thanks for sharing.</td>', 'I always enjoy reflections.  It gives me a chance to imagine and create my own story behind the true subject before me.  Of course the car brand is great but my attention is directed to the broken Y and the oval shapes being framed by the aggressive red and yellow lines above and bellow.  I love a mystery and you''ve given me one that holds my interest Sherlock.  Keeping the blue colours a mystery keeps me in love with the photo.  Thanks for sharing.', '2004-08-18 05:32:09.000000', NULL, 1),
(864792, 98340, 12061, '<td valign="top">Boost the contrast and saturation to create a more neon look.</td>', 'Boost the contrast and saturation to create a more neon look.', '2004-08-18 05:33:15.000000', NULL, 1),
(864794, 97517, 24511, '<td valign="top">Theme of work and school was a real downer for me.  Neon pens are great for the challenge but tough on moral.  You get a few points but don''t forget...some of us are still on vacation.  Thanks!</td>', 'Theme of work and school was a real downer for me.  Neon pens are great for the challenge but tough on moral.  You get a few points but don''t forget...some of us are still on vacation.  Thanks!', '2004-08-18 05:34:39.000000', NULL, 1),
(864797, 98458, 12061, '<td valign="top">Neat idea, not sure if I do like the layering effect, this one stands out though nontheless. Good work.</td>', 'Neat idea, not sure if I do like the layering effect, this one stands out though nontheless. Good work.', '2004-08-18 05:36:39.000000', NULL, 1),
(864799, 98269, 12061, '<td valign="top">Nice job! Ribbon? Hmmm ... Perhaps. =)</td>', 'Nice job! Ribbon? Hmmm ... Perhaps. =)', '2004-08-18 05:37:58.000000', NULL, 1),
(864800, 97600, 12061, '<td valign="top">I don''t like the border .. I would love this shot if it were properly in focus .. the colors are great and everything but the lack of focus is too bad..</td>', 'I don''t like the border .. I would love this shot if it were properly in focus .. the colors are great and everything but the lack of focus is too bad..', '2004-08-18 05:39:04.000000', NULL, 1),
