(864806, 97522, 12061, '<td valign="top">lol on the title ... nice shot - the border isn''t doing it for me, but thats just personal preference. Great neon subject =)</td>', 'lol on the title ... nice shot - the border isn''t doing it for me, but thats just personal preference. Great neon subject =)', '2004-08-18 05:44:18.000000', NULL, 1),
