(865356, 98318, 24951, '<td valign="top">Great abstract. Love the blue/ green. Good composition.</td>', 'Great abstract. Love the blue/ green. Good composition.', '2004-08-18 10:21:28.000000', NULL, 1),
(865358, 97665, 12611, '<td valign="top">Is that chain link? I like the church style stained glass elements to this and I like the rust colored lighting.<br/>I guess my criticism would be that there would really be no appeal to print this out and put it on my wall. But maybe this abstract would be better blurred out a bit- soft focus or gaussian blur if you will, and that would add the the unique quality of the shot. Don''t let my comment on the sale-ability of the shot alter what you have done. Its really quite interesting.</td>', 'Is that chain link? I like the church style stained glass elements to this and I like the rust colored lighting.I guess my criticism would be that there would really be no appeal to print this out and put it on my wall. But maybe this abstract would be better blurred out a bit- soft focus or gaussian blur if you will, and that would add the the unique quality of the shot. Don''t let my comment on the sale-ability of the shot alter what you have done. Its really quite interesting.', '2004-08-18 10:21:59.000000', NULL, 1),
(865359, 98458, 12611, '<td valign="top">very colrful. I like the colors you chose, they are very seventies and the buttons only enhance this. I like the vintage quality of the very separate tones of the shot. nice!</td>', 'very colrful. I like the colors you chose, they are very seventies and the buttons only enhance this. I like the vintage quality of the very separate tones of the shot. nice!', '2004-08-18 10:23:15.000000', NULL, 1),
