(866059, 98481, 117, '<td valign="top">more focus use a tripod or some stable for you camera to sit on.</td>', 'more focus use a tripod or some stable for you camera to sit on.', '2004-08-18 15:59:52.000000', NULL, 1),
(866065, 98335, 25576, '<td valign="top">Cracked me up.  The drool is a nice - if not disgusting - effect.   I really like how the neon refelects in the glass.</td>', 'Cracked me up.  The drool is a nice - if not disgusting - effect.   I really like how the neon refelects in the glass.', '2004-08-18 16:02:05.000000', NULL, 1),
