(866093, 98457, 8054, '<td valign="top">Very grainy and, perhaps oversharpened. I think this would have looked better if you used a polarizer to cut the reflections and give the cactus a floating appearance.</td>', 'Very grainy and, perhaps oversharpened. I think this would have looked better if you used a polarizer to cut the reflections and give the cactus a floating appearance.', '2004-08-18 16:21:07.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(866096, 98456, 8054, '<td valign="top">Overall nice composition but has lots of grain/noise.</td>', 'Overall nice composition but has lots of grain/noise.', '2004-08-18 16:22:43.000000', NULL, 1),
(866107, 97522, 21430, '<td valign="top">The border pisses me off. It is to bright and destracting.<br/> <br/> The rest of the image is quite nice. I like the way you were able to capture the fish without being slapped with the issues common to fishtank photography.<br/> <br/>  I am sorry if my initial statement sounded very harsh, but it was the first thing that popped into my head when your image loaded and I think it is important that you are aware of initial reactions to your work, once I got past the border the rest of the image is very nice.</td>', 'The border pisses me off. It is to bright and destracting.  The rest of the image is quite nice. I like the way you were able to capture the fish without being slapped with the issues common to fishtank photography.   I am sorry if my initial statement sounded very harsh, but it was the first thing that popped into my head when your image loaded and I think it is important that you are aware of initial reactions to your work, once I got past the border the rest of the image is very nice.', '2004-08-18 16:28:44.000000', NULL, 1),
(866112, 98187, 21430, '<td valign="top">I really want to see how you did this. Did you zoom in or out the lense/camera while this image was being captured?<br/> <br/>  It is a nice caputre of color and is definately a neon subject. The only issues I see is the extra dead space in the top of the image and the cutting off of the bottom of the subject. It almost looks as if the whole subject could have been in the image if the camera was physically higher then it was.</td>', 'I really want to see how you did this. Did you zoom in or out the lense/camera while this image was being captured?   It is a nice caputre of color and is definately a neon subject. The only issues I see is the extra dead space in the top of the image and the cutting off of the bottom of the subject. It almost looks as if the whole subject could have been in the image if the camera was physically higher then it was.', '2004-08-18 16:31:45.000000', NULL, 1),
(866158, 98498, 327, '<td valign="top">This is really very nice, could be a Revlon ad for nailpolish or lipstick. Nice going.</td>', 'This is really very nice, could be a Revlon ad for nailpolish or lipstick. Nice going.', '2004-08-18 17:14:40.000000', NULL, 1),
(866163, 97959, 327, '<td valign="top">Great idea for the challenge, just too much such.</td>', 'Great idea for the challenge, just too much such.', '2004-08-18 17:17:33.000000', NULL, 1),
(866178, 98235, 24659, '<td valign="top">6, but mostly for content!  =)</td>', '6, but mostly for content!  =)', '2004-08-18 17:30:42.000000', NULL, 1),
(866185, 98391, 24659, '<td valign="top">Creative use of neon!  I like your concept a lot.  Good job!</td>', 'Creative use of neon!  I like your concept a lot.  Good job!', '2004-08-18 17:38:44.000000', NULL, 1),
(866189, 98088, 25343, '<td valign="top">Great shot..but I am lost as to the "neon"...?</td>', 'Great shot..but I am lost as to the "neon"...?', '2004-08-18 17:41:44.000000', NULL, 1),
(866200, 98486, 21430, '<td valign="top">Very unique take on this challenge. Hitting the Periodic Table of Elements is an excellent choice. I also like the use of the highlighter to bring out the subject.<br/> <br/>Great shot, nice DOF use as well.</td>', 'Very unique take on this challenge. Hitting the Periodic Table of Elements is an excellent choice. I also like the use of the highlighter to bring out the subject. Great shot, nice DOF use as well.', '2004-08-18 17:45:04.000000', NULL, 1),
(866201, 98513, 21430, '<td valign="top">This shot meets the challenge, but is kind of boring. Perhaps with a different angle or a sharper end product would provide more oomph to this image. There''s just a lot of dead space that really detracts from the neon subject matter.</td>', 'This shot meets the challenge, but is kind of boring. Perhaps with a different angle or a sharper end product would provide more oomph to this image. There''s just a lot of dead space that really detracts from the neon subject matter.', '2004-08-18 17:46:35.000000', NULL, 1),
