(866613, 98521, 19978, '<td valign="top">An interesting composition adding creativity to an otherwise uninteresting sign. The angle you''ve chosen highlights some unusual textures and context that would normally been invisible. Great crop and effect. One of the best "sign shots" in the challenge.</td>', 'An interesting composition adding creativity to an otherwise uninteresting sign. The angle you''ve chosen highlights some unusual textures and context that would normally been invisible. Great crop and effect. One of the best "sign shots" in the challenge.', '2004-08-18 22:30:04.000000', NULL, 1),
(866616, 97563, 25065, '<td valign="top">Whoa, one more mirror and you might accidently copy yourself... Kudos for an original picture idea.</td>', 'Whoa, one more mirror and you might accidently copy yourself... Kudos for an original picture idea.', '2004-08-18 22:30:36.000000', NULL, 1),
(866617, 98187, 19978, '<td valign="top">A great find. I like everything about it except the crop. Too bad you had to lose the tip of the bottom petal. Otherwise perfect.</td>', 'A great find. I like everything about it except the crop. Too bad you had to lose the tip of the bottom petal. Otherwise perfect.', '2004-08-18 22:30:54.000000', NULL, 1),
(866619, 97673, 25065, '<td valign="top">Ow, The pun Police are getting a call tonight! Original idea, funny, quality photo.</td>', 'Ow, The pun Police are getting a call tonight! Original idea, funny, quality photo.', '2004-08-18 22:31:55.000000', NULL, 1),
(866620, 98109, 19978, '<td valign="top">A very interesting response to the challenge. I forget what these things are called, but it makes a very good shot. I like your choice of composition. Very well done.</td>', 'A very interesting response to the challenge. I forget what these things are called, but it makes a very good shot. I like your choice of composition. Very well done.', '2004-08-18 22:32:01.000000', NULL, 1),
