(866637, 97557, 25065, '<td valign="top">Interesting. Trippy. quite original. Have a 7.</td>', 'Interesting. Trippy. quite original. Have a 7.', '2004-08-18 22:41:52.000000', NULL, 1),
(866639, 98517, 25065, '<td valign="top">I like how the numbers come from different directions.</td>', 'I like how the numbers come from different directions.', '2004-08-18 22:42:24.000000', NULL, 1),
