(867013, 97479, 19035, '<td valign="top">My kids just rode a ride by this name at our local festival in Ohio this past weekend, nice shot - 8 -</td>', 'My kids just rode a ride by this name at our local festival in Ohio this past weekend, nice shot - 8 -', '2004-08-19 02:44:39.000000', NULL, 1),
(867019, 97306, 21362, '<td valign="top">Great photo that stands out in this challenge. Might argue the frame is too cut in half by the horizon... but it''s not a huge problem. Very good. :)</td>', 'Great photo that stands out in this challenge. Might argue the frame is too cut in half by the horizon... but it''s not a huge problem. Very good. :)', '2004-08-19 02:58:10.000000', NULL, 1),
(867022, 97780, 21362, '<td valign="top">I''m confused by this one. That red kite-shaped neon thing looks strangly out of place but I can''t figure out what it is to begin with. <br/> <br/>Looks it was taken through a car window giving a snap-shot feel. Don''t like that power line that runs right through the center of the image.</td>', 'I''m confused by this one. That red kite-shaped neon thing looks strangly out of place but I can''t figure out what it is to begin with.  Looks it was taken through a car window giving a snap-shot feel. Don''t like that power line that runs right through the center of the image.', '2004-08-19 03:00:57.000000', NULL, 1),
(867023, 97479, 21362, '<td valign="top">Great color and movement.</td>', 'Great color and movement.', '2004-08-19 03:01:20.000000', NULL, 1),
