(867037, 98270, 25017, '<td valign="top">I like the composition overall but it really does not grab me for the neon theme, but altogether its good</td>', 'I like the composition overall but it really does not grab me for the neon theme, but altogether its good', '2004-08-19 03:16:19.000000', NULL, 1),
(867038, 97479, 23561, '<td valign="top">Very nice. I like how the lights seem to move. Lots of color. Best use of neon sign. 10</td>', 'Very nice. I like how the lights seem to move. Lots of color. Best use of neon sign. 10', '2004-08-19 03:16:34.000000', NULL, 1),
