(867041, 98187, 23561, '<td valign="top">I like the effect you captured. Only thing I wish was different was the bottom, I would have liked to see the full effect instead of it being cut off. 8</td>', 'I like the effect you captured. Only thing I wish was different was the bottom, I would have liked to see the full effect instead of it being cut off. 8', '2004-08-19 03:20:04.000000', NULL, 1),
(867049, 97522, 21362, '<td valign="top">I really don''t care for the border (and those don''t usually bug me) -- it''s just overkill here. Beautiful fish though. Great subject for the challenge. I practically need to squint to look at it!</td>', 'I really don''t care for the border (and those don''t usually bug me) -- it''s just overkill here. Beautiful fish though. Great subject for the challenge. I practically need to squint to look at it!', '2004-08-19 03:38:19.000000', NULL, 1),
(867054, 98087, 23016, '<td valign="top">The colors are not so vivid, a modification of the saturation probably will get a better photo for this challenge.</td>', 'The colors are not so vivid, a modification of the saturation probably will get a better photo for this challenge.', '2004-08-19 04:22:52.000000', NULL, 1),
