(867057, 97800, 23016, '<td valign="top">Out of focus? Probably, for this challenge, a closer cropping of the cat''s eye will get a better photo.</td>', 'Out of focus? Probably, for this challenge, a closer cropping of the cat''s eye will get a better photo.', '2004-08-19 04:26:37.000000', NULL, 1),
(867064, 97754, 22392, '<td valign="top">nice sharp, but the composition is not very interesting. 6</td>', 'nice sharp, but the composition is not very interesting. 6', '2004-08-19 04:57:54.000000', NULL, 1),
(867070, 98374, 25656, '<td valign="top">Great shot. Real explosion.</td>', 'Great shot. Real explosion.', '2004-08-19 05:19:07.000000', NULL, 1),
(867077, 98230, 24976, '<td valign="top">cool stuff, has a great outer space feel to it. I like the red and blues used and the beams of light making slight glows where they hit the ''planets''</td>', 'cool stuff, has a great outer space feel to it. I like the red and blues used and the beams of light making slight glows where they hit the ''planets''', '2004-08-19 05:30:24.000000', NULL, 1),
(867079, 98243, 24976, '<td valign="top">haha, nice title. I love the reflection and the overall sharpness/ crispness in the image. Great photo. 9</td>', 'haha, nice title. I love the reflection and the overall sharpness/ crispness in the image. Great photo. 9', '2004-08-19 05:31:24.000000', NULL, 1),
(867080, 98086, 24976, '<td valign="top">awesome, a modern photographic Mondrian. 9</td>', 'awesome, a modern photographic Mondrian. 9', '2004-08-19 05:31:55.000000', NULL, 1),
(867083, 98225, 24976, '<td valign="top">the composition is really strong, i cant really put it into words but it has a mesmirizing effect. It leads the eye very well through the image and keeps it in, never allowing it to wander off the photo. great job, could have used a bit less noise but still a great job! 9</td>', 'the composition is really strong, i cant really put it into words but it has a mesmirizing effect. It leads the eye very well through the image and keeps it in, never allowing it to wander off the photo. great job, could have used a bit less noise but still a great job! 9', '2004-08-19 05:34:01.000000', NULL, 1),
(867084, 97756, 24976, '<td valign="top">i love the orange-red color</td>', 'i love the orange-red color', '2004-08-19 05:34:26.000000', NULL, 1),
(867087, 98520, 24976, '<td valign="top">It seems like you shook your camera to get this effect, the downside to that is the letters are blurry.</td>', 'It seems like you shook your camera to get this effect, the downside to that is the letters are blurry.', '2004-08-19 05:36:35.000000', NULL, 1),
(867089, 97130, 24976, '<td valign="top">seems like you went through some camera shake on this one.</td>', 'seems like you went through some camera shake on this one.', '2004-08-19 05:37:18.000000', NULL, 1),
(867147, 98076, 23137, '<td valign="top">an interesting perspective, would have looked better toning down the brightness on the trunk though. 8</td>', 'an interesting perspective, would have looked better toning down the brightness on the trunk though. 8', '2004-08-19 07:19:26.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(867148, 97869, 23137, '<td valign="top">like ur idea, certainly beats most of the usual neon signs!! gives quite an eerie feeling, in a good way :) 9</td>', 'like ur idea, certainly beats most of the usual neon signs!! gives quite an eerie feeling, in a good way :) 9', '2004-08-19 07:20:59.000000', NULL, 1),
(867151, 98436, 23137, '<td valign="top">that looks like an interesting building, and u''ve captured the neon colours complementing it. well done 9<br/></td>', 'that looks like an interesting building, and u''ve captured the neon colours complementing it. well done 9', '2004-08-19 07:22:54.000000', NULL, 1),
(867154, 98257, 23137, '<td valign="top">like ur idea for this challenge, and the image looks interesting, shows the striking colour of neon in the dark background. well done.  8</td>', 'like ur idea for this challenge, and the image looks interesting, shows the striking colour of neon in the dark background. well done.  8', '2004-08-19 07:25:03.000000', NULL, 1),
(867158, 98109, 23137, '<td valign="top">quite captivating...interesting entry for this challenge, and is unique. good work. 8</td>', 'quite captivating...interesting entry for this challenge, and is unique. good work. 8', '2004-08-19 07:28:18.000000', NULL, 1),
(867160, 98502, 23137, '<td valign="top">like the neon purple in it, and the lines, which give it an overall sense of detail. good job 8</td>', 'like the neon purple in it, and the lines, which give it an overall sense of detail. good job 8', '2004-08-19 07:29:45.000000', NULL, 1),
(867163, 98387, 23137, '<td valign="top">i quite like this image, the colours and the design of the ferry wheel, and the angle u''ve taken it in. good luck. 7</td>', 'i quite like this image, the colours and the design of the ferry wheel, and the angle u''ve taken it in. good luck. 7', '2004-08-19 07:31:06.000000', NULL, 1),
(867166, 98224, 23137, '<td valign="top">quite an interesting shot, it somehow feels both peaceful cause of the sunlight shining through the tress, and at the same time, somewhat of a haphazard look, showing in the stream. good combo. 8</td>', 'quite an interesting shot, it somehow feels both peaceful cause of the sunlight shining through the tress, and at the same time, somewhat of a haphazard look, showing in the stream. good combo. 8', '2004-08-19 07:32:30.000000', NULL, 1),
(867183, 98235, 20204, '<td valign="top">It''s difficult to see how any photographic elements contributed to this work, vs. the pre-existing elements of the neon art.  It looks more like a head-on shot of prior art which is technically not allowed by challenge rules.  Since I don''t know exactly what was done, I''m voting as though this shot was legitimate, but something to think about.</td>', 'It''s difficult to see how any photographic elements contributed to this work, vs. the pre-existing elements of the neon art.  It looks more like a head-on shot of prior art which is technically not allowed by challenge rules.  Since I don''t know exactly what was done, I''m voting as though this shot was legitimate, but something to think about.', '2004-08-19 08:32:07.000000', NULL, 1),
(867186, 98076, 20204, '<td valign="top">I''m not crazy about the posterized effect, but its a very cool composition.</td>', 'I''m not crazy about the posterized effect, but its a very cool composition.', '2004-08-19 08:33:31.000000', NULL, 1),
(867190, 97888, 20204, '<td valign="top">Maybe I''m missing an abstract element here, but I''m just seeing a totally out of focus frame.</td>', 'Maybe I''m missing an abstract element here, but I''m just seeing a totally out of focus frame.', '2004-08-19 08:35:57.000000', NULL, 1),
(867197, 98505, 20204, '<td valign="top">I''m not seeing any photographic elements which build on the sign itself, or show photographic creativity in laying out the shot.  If we consider the neon sign to be a neon artist''s work, that would make this image a direct photo of prior art, which is not permitted in the contest rules.  It''s a gray area, so I''m not recommending this shot for DQ, but my vote reflects the fact that while this is a technically comptetant image, it is not using observable (to me) unique interpretation, perspective, lighting, or photoediting.</td>', 'I''m not seeing any photographic elements which build on the sign itself, or show photographic creativity in laying out the shot.  If we consider the neon sign to be a neon artist''s work, that would make this image a direct photo of prior art, which is not permitted in the contest rules.  It''s a gray area, so I''m not recommending this shot for DQ, but my vote reflects the fact that while this is a technically comptetant image, it is not using observable (to me) unique interpretation, perspective, lighting, or photoediting.', '2004-08-19 08:39:37.000000', NULL, 1),
(867202, 98458, 24389, '<td valign="top">i find it that people on this site don''t really like borders, but i think this border is really great for this photo. i like your idea, and the title fits perfectly! great job!</td>', 'i find it that people on this site don''t really like borders, but i think this border is really great for this photo. i like your idea, and the title fits perfectly! great job!', '2004-08-19 08:56:32.000000', NULL, 1),
