(867264, 98340, 24951, '<td valign="top">Good and clear and bright</td>', 'Good and clear and bright', '2004-08-19 09:42:29.000000', NULL, 1),
(867266, 98458, 19841, '<td valign="top">The problem with trying to add interest with a border is that you wind up with a border that upstages your subject.   It''s a good idea that didn''t quite work.  The picture is nice on its own.</td>', 'The problem with trying to add interest with a border is that you wind up with a border that upstages your subject.   It''s a good idea that didn''t quite work.  The picture is nice on its own.', '2004-08-19 09:44:16.000000', NULL, 1),
