(867638, 98500, 19608, '<td valign="top">Nice zooming!  Good subject - and very well photographed.</td>', 'Nice zooming!  Good subject - and very well photographed.', '2004-08-19 14:51:29.000000', NULL, 1),
(867640, 98391, 19608, '<td valign="top">Excellent juxtaposition!  A great idea very well done.  The "camera" is just a bit soft, but not that serious.  Black background is great.  I hope the flower haters don''t zap you!</td>', 'Excellent juxtaposition!  A great idea very well done.  The "camera" is just a bit soft, but not that serious.  Black background is great.  I hope the flower haters don''t zap you!', '2004-08-19 14:53:42.000000', NULL, 1),
(867643, 97873, 19608, '<td valign="top">Oh, this idea is great - so painterly.  If only the white areas weren''t so bright, it would be way up in th stack. But the way it is, the white is overpowering.</td>', 'Oh, this idea is great - so painterly.  If only the white areas weren''t so bright, it would be way up in th stack. But the way it is, the white is overpowering.', '2004-08-19 14:56:13.000000', NULL, 1),
(867653, 98315, 23146, '<td valign="top">Nice picture, but it´s a little bit out of focus. Did you use a tripod?</td>', 'Nice picture, but it´s a little bit out of focus. Did you use a tripod?', '2004-08-19 15:22:32.000000', NULL, 1),
(867654, 98505, 23146, '<td valign="top">A very  nice classic neon picture, great shot.</td>', 'A very  nice classic neon picture, great shot.', '2004-08-19 15:23:17.000000', NULL, 1),
(867660, 97869, 23146, '<td valign="top">very nice shot and wonderful idea</td>', 'very nice shot and wonderful idea', '2004-08-19 15:26:07.000000', NULL, 1),
(867690, 98514, 16493, '<td valign="top">Good neon colors, looks a bit too saturated in some parts, lighting could me a bit too harsh</td>', 'Good neon colors, looks a bit too saturated in some parts, lighting could me a bit too harsh', '2004-08-19 15:50:11.000000', NULL, 1),
