(867788, 98108, 3102, '<td valign="top">Well, if nothing else, you and I think somewhat alike... I was contemplating a shot of someone purchasing a knee for the botany ("bought-a-knee") challenge :)  UPDATE... and now that I''m voting on the Botany challenge, I see someone else (you?) had THAT same idea!</td>', 'Well, if nothing else, you and I think somewhat alike... I was contemplating a shot of someone purchasing a knee for the botany ("bought-a-knee") challenge :)  UPDATE... and now that I''m voting on the Botany challenge, I see someone else (you?) had THAT same idea!', '2004-08-19 17:33:39.000000', NULL, 1),
(867789, 98193, 24659, '<td valign="top">Interesting variation!</td>', 'Interesting variation!', '2004-08-19 17:33:41.000000', NULL, 1),
(867794, 98088, 24659, '<td valign="top">Ummm.  Theme is "Neon."  Sorry.</td>', 'Ummm.  Theme is "Neon."  Sorry.', '2004-08-19 17:39:06.000000', NULL, 1),
(867795, 97625, 24659, '<td valign="top">Good use of neon, very busy but very visually stimulating!  I like this a lot, after looking at all the non-neon photos...</td>', 'Good use of neon, very busy but very visually stimulating!  I like this a lot, after looking at all the non-neon photos...', '2004-08-19 17:41:47.000000', NULL, 1),
(867796, 98481, 24659, '<td valign="top">A little on the blurry side.</td>', 'A little on the blurry side.', '2004-08-19 17:42:02.000000', NULL, 1),
(867798, 97479, 24659, '<td valign="top">Wheee!  Good job.  I don''t think it''s actually neon, just colored bulbs, but the bright colors override that!</td>', 'Wheee!  Good job.  I don''t think it''s actually neon, just colored bulbs, but the bright colors override that!', '2004-08-19 17:43:07.000000', NULL, 1),
