(867808, 98108, 18080, '<td valign="top">Lovely and crisp, excellently cheeky title, would''ve been a ten if the jeans were blue. 9</td>', 'Lovely and crisp, excellently cheeky title, would''ve been a ten if the jeans were blue. 9', '2004-08-19 17:51:16.000000', NULL, 1),
(867814, 98254, 24969, '<td valign="top">Love this! Came back to bump it from 9 to 10. Excellent work.</td>', 'Love this! Came back to bump it from 9 to 10. Excellent work.', '2004-08-19 17:57:19.000000', NULL, 1),
