(867917, 97756, 22310, '<td valign="top">Very nice and creative.</td>', 'Very nice and creative.', '2004-08-19 19:08:33.000000', NULL, 1),
(867919, 98187, 22310, '<td valign="top">Nicely done.  Jumps off of the page at me.</td>', 'Nicely done.  Jumps off of the page at me.', '2004-08-19 19:09:42.000000', NULL, 1),
(867921, 98117, 22310, '<td valign="top">Nice photo, creative.  The title is a little confusing as I am not sure why this is a requiem rather than possibly a prelude.</td>', 'Nice photo, creative.  The title is a little confusing as I am not sure why this is a requiem rather than possibly a prelude.', '2004-08-19 19:12:29.000000', NULL, 1),
(867926, 98430, 22310, '<td valign="top">Nicely done.  The soft light and long exposure make for an erie three dimentional effect.  Hope it gets a ribbon.</td>', 'Nicely done.  The soft light and long exposure make for an erie three dimentional effect.  Hope it gets a ribbon.', '2004-08-19 19:14:09.000000', NULL, 1),
(867927, 97869, 21714, '<td valign="top">Great idea well executed. I feel that increasing the contrast a bit will make this shot even more effective.</td>', 'Great idea well executed. I feel that increasing the contrast a bit will make this shot even more effective.', '2004-08-19 19:14:47.000000', NULL, 1),
(867929, 98046, 22310, '<td valign="top">Excellent idea!  Very creative!  I especially like the soft red light gradient across the face.  Should be a ribbon.</td>', 'Excellent idea!  Very creative!  I especially like the soft red light gradient across the face.  Should be a ribbon.', '2004-08-19 19:15:55.000000', NULL, 1),
(867930, 98257, 12573, '<td valign="top">Well, I love the composition.  The placement of the light in the frame is very good.  The story being told here is powerful and engaging.  I hate to nitpick, but you''ve apparently over sharpened this image (haloing apparent on hard edges) and there is some JPG compression artifacts.  Other than that and your misspelled title, it''s altogether very nice.  Keep it up!</td>', 'Well, I love the composition.  The placement of the light in the frame is very good.  The story being told here is powerful and engaging.  I hate to nitpick, but you''ve apparently over sharpened this image (haloing apparent on hard edges) and there is some JPG compression artifacts.  Other than that and your misspelled title, it''s altogether very nice.  Keep it up!', '2004-08-19 19:16:24.000000', NULL, 1),
(867932, 98499, 22310, '<td valign="top">Interesting shot.  I look forward to see how it was done.</td>', 'Interesting shot.  I look forward to see how it was done.', '2004-08-19 19:17:19.000000', NULL, 1),
(867933, 97508, 22310, '<td valign="top">I like it.  It has that "warp drive" feeling of motion.</td>', 'I like it.  It has that "warp drive" feeling of motion.', '2004-08-19 19:18:26.000000', NULL, 1),
(867936, 98108, 20941, '<td valign="top">Thank You!</td>', 'Thank You!', '2004-08-19 19:20:11.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(867937, 98269, 21714, '<td valign="top">Excellent idea. Not sure about the horizontal placing of the subject. I think a vertical shot or      bait coming diagonally into the shot would make it even more interesting.  Nice job.</td>', 'Excellent idea. Not sure about the horizontal placing of the subject. I think a vertical shot or      bait coming diagonally into the shot would make it even more interesting.  Nice job.', '2004-08-19 19:20:28.000000', NULL, 1),
(867938, 98331, 12573, '<td valign="top">Nifty.  I''m trying to figure out how you achieved the stuttering of light.  It''s keeping me interested and that''s worth something.  I wish it were a little less noisy near the sign on the left.  Anxious to know if anything special went into this effect.</td>', 'Nifty.  I''m trying to figure out how you achieved the stuttering of light.  It''s keeping me interested and that''s worth something.  I wish it were a little less noisy near the sign on the left.  Anxious to know if anything special went into this effect.', '2004-08-19 19:20:58.000000', NULL, 1),
(867942, 98109, 22310, '<td valign="top">Nice photo, good exposure and DOF.  Minor point but I think the title is a little distracting.</td>', 'Nice photo, good exposure and DOF.  Minor point but I think the title is a little distracting.', '2004-08-19 19:23:23.000000', NULL, 1),
(867944, 97553, 20941, '<td valign="top">ok, finished voting and this is my top pick...Brillliant, in more ways than one!! 10</td>', 'ok, finished voting and this is my top pick...Brillliant, in more ways than one!! 10', '2004-08-19 19:24:13.000000', NULL, 1),
(867951, 98225, 22310, '<td valign="top">Very creative, I like it.  Compositionally a little off balance to the left.</td>', 'Very creative, I like it.  Compositionally a little off balance to the left.', '2004-08-19 19:26:43.000000', NULL, 1),
(867954, 97560, 12573, '<td valign="top">In spite of the current sentiment in the forums, this kind of treatment of neon signs is not easy.  You have composed this sign beautifully.  It takes me back to an age of glamour long past (not that I ever knew that age).  You force me to "look up" at the sign with the wide angle view, causing me to feel like I''m there on the sidewalk.  I give you a 10 for composing what I feel to be the most fitting image of the challenge (though not necessarily the most technically perfect).</td>', 'In spite of the current sentiment in the forums, this kind of treatment of neon signs is not easy.  You have composed this sign beautifully.  It takes me back to an age of glamour long past (not that I ever knew that age).  You force me to "look up" at the sign with the wide angle view, causing me to feel like I''m there on the sidewalk.  I give you a 10 for composing what I feel to be the most fitting image of the challenge (though not necessarily the most technically perfect).', '2004-08-19 19:29:09.000000', NULL, 1),
(867955, 98076, 22310, '<td valign="top">Cool idea.  The DOF and balance are just right to my eye.  I am not sure the color says "neon" rather than maybe just "blue". 6</td>', 'Cool idea.  The DOF and balance are just right to my eye.  I am not sure the color says "neon" rather than maybe just "blue". 6', '2004-08-19 19:29:21.000000', NULL, 1),
(867957, 98109, 21714, '<td valign="top">Very cool image. Creative and nicely done.</td>', 'Very cool image. Creative and nicely done.', '2004-08-19 19:30:00.000000', NULL, 1),
(867958, 98387, 22310, '<td valign="top">I expected more ferris wheel shots in this challenge.  Nice composition and exposure. 6</td>', 'I expected more ferris wheel shots in this challenge.  Nice composition and exposure. 6', '2004-08-19 19:30:51.000000', NULL, 1),
(867964, 97754, 12573, '<td valign="top">Would have been so much better if the people in the shot were actually blurred, further denoting the "hussle and bustle" you''ve captured.  I probably would have focused on either the newstand -or- the restaurant, but not both.</td>', 'Would have been so much better if the people in the shot were actually blurred, further denoting the "hussle and bustle" you''ve captured.  I probably would have focused on either the newstand -or- the restaurant, but not both.', '2004-08-19 19:39:12.000000', NULL, 1),
(867967, 98116, 12573, '<td valign="top">Very similar idea to another shot and you''ve done a better job getting the idea across.  Generally speaking, this shot seems to look better when it''s a little darker outside than you''ve taken.  But don''t make it too dark or you''ll lose the detail of the vehicle, like what happened in the other similar car reflection photo.</td>', 'Very similar idea to another shot and you''ve done a better job getting the idea across.  Generally speaking, this shot seems to look better when it''s a little darker outside than you''ve taken.  But don''t make it too dark or you''ll lose the detail of the vehicle, like what happened in the other similar car reflection photo.', '2004-08-19 19:42:33.000000', NULL, 1),
(867969, 97410, 12573, '<td valign="top">Very cool abstract.  It''s interesting how much information lies in those three little letters.  We know this a picture of some sort of electronic device, but little else can be derived.  The placement of the focal element in the frame is quite good.  I dunno, I''m just a sucker for these shots. 7.</td>', 'Very cool abstract.  It''s interesting how much information lies in those three little letters.  We know this a picture of some sort of electronic device, but little else can be derived.  The placement of the focal element in the frame is quite good.  I dunno, I''m just a sucker for these shots. 7.', '2004-08-19 19:44:43.000000', NULL, 1),
(867987, 98498, 12573, '<td valign="top">This is quite nice and is a potential ribbon winner. The texture in the fake flowers is not really doing anything for me though and I wonder if a more silky flower (or real flowers for that matter) would have improved it.</td>', 'This is quite nice and is a potential ribbon winner. The texture in the fake flowers is not really doing anything for me though and I wonder if a more silky flower (or real flowers for that matter) would have improved it.', '2004-08-19 20:06:36.000000', NULL, 1),
(867989, 98383, 12573, '<td valign="top">I don''t care for the title, but I dig the abstract nature of the photo.  I find myself wanting to know what I''m looking at and not being particularly annoyed that I can''t figure it out.  The green and blue are strikingly complementary and fit the challenge superbly.  What could you improve?  Well, maybe make the bright neon green thing perfectly straight up and down.  Other than that, it''s slightly noisy near the bottom in the darker areas.  I really enjoyed this though. 8.</td>', 'I don''t care for the title, but I dig the abstract nature of the photo.  I find myself wanting to know what I''m looking at and not being particularly annoyed that I can''t figure it out.  The green and blue are strikingly complementary and fit the challenge superbly.  What could you improve?  Well, maybe make the bright neon green thing perfectly straight up and down.  Other than that, it''s slightly noisy near the bottom in the darker areas.  I really enjoyed this though. 8.', '2004-08-19 20:07:10.000000', NULL, 1),
(867991, 98177, 12573, '<td valign="top">Title is a little wordy, but who cares.  THe inclusion of the photographer is important here and I''m glad you thought to do it.  Otherwise, it''s a pretty flat image.  Lighting is quite harsh and would have been improved by catching the same scene later in the evening, with maybe some spot lights on the bright wall to accentuate.</td>', 'Title is a little wordy, but who cares.  THe inclusion of the photographer is important here and I''m glad you thought to do it.  Otherwise, it''s a pretty flat image.  Lighting is quite harsh and would have been improved by catching the same scene later in the evening, with maybe some spot lights on the bright wall to accentuate.', '2004-08-19 20:09:55.000000', NULL, 1),
(867995, 98258, 22036, '<td valign="top">Little blury</td>', 'Little blury', '2004-08-19 20:16:05.000000', NULL, 1),
