(868249, 97306, 21611, '<td valign="top">really nice shot. my favorite of the whole contest. that is really outstanding work.on a scale of 1 to 10.......10</td>', 'really nice shot. my favorite of the whole contest. that is really outstanding work.on a scale of 1 to 10.......10', '2004-08-20 01:31:00.000000', NULL, 1),
(868250, 98315, 13759, '<td valign="top">Tanks to your engage to this challenge. Are you newbie here? Your image are very untought. You passes on a street, saw a neon, take the camera and... click. This is only a snapshot. In a picture of this type you need to use a tripod, to ensure sharpness and do a bit with composition. Ok, this was bad, but continue to try, improving your skills, with us.</td>', 'Tanks to your engage to this challenge. Are you newbie here? Your image are very untought. You passes on a street, saw a neon, take the camera and... click. This is only a snapshot. In a picture of this type you need to use a tripod, to ensure sharpness and do a bit with composition. Ok, this was bad, but continue to try, improving your skills, with us.', '2004-08-20 01:32:18.000000', NULL, 1),
(868255, 98094, 13759, '<td valign="top">Greatest. Is was stunning by the effect.</td>', 'Greatest. Is was stunning by the effect.', '2004-08-20 01:39:49.000000', NULL, 1),
