(868265, 97729, 25468, '<td valign="top">This is absolutely beautiful. Excellent take on the ''Neon'' catagory. Blue and Orange, reminds me of home.</td>', 'This is absolutely beautiful. Excellent take on the ''Neon'' catagory. Blue and Orange, reminds me of home.', '2004-08-20 01:57:40.000000', NULL, 1),
(868266, 97553, 25468, '<td valign="top">I would have given this a higher rating if it hadn''t been for all the pink fuzzing up the foreground. Reminds me of a B-movie. Love em''</td>', 'I would have given this a higher rating if it hadn''t been for all the pink fuzzing up the foreground. Reminds me of a B-movie. Love em''', '2004-08-20 01:59:29.000000', NULL, 1),
(868268, 97127, 25468, '<td valign="top">Pardon my french, but this is bad ass! Great execution of a brilliant idea.</td>', 'Pardon my french, but this is bad ass! Great execution of a brilliant idea.', '2004-08-20 02:00:54.000000', NULL, 1),
(868269, 98191, 8054, '<td valign="top">I think this is my first 10 in this entire challenge. Love the colors, composition and focus! I think it would look better if it was brighter to help show off the neon but maybe you would have introduced noise or other unwanted fringe benefits. Great job and definitely a ribbon winner.</td>', 'I think this is my first 10 in this entire challenge. Love the colors, composition and focus! I think it would look better if it was brighter to help show off the neon but maybe you would have introduced noise or other unwanted fringe benefits. Great job and definitely a ribbon winner.', '2004-08-20 02:01:45.000000', NULL, 1),
(868270, 98353, 25468, '<td valign="top">I rate this highly based on originality alone. If you include technique and brilliance into it it''s damn near perfect.</td>', 'I rate this highly based on originality alone. If you include technique and brilliance into it it''s damn near perfect.', '2004-08-20 02:03:50.000000', NULL, 1),
(868274, 97725, 25468, '<td valign="top">Congradulations to the author of this photo for posting the only sign I found acceptable and quite stunning.</td>', 'Congradulations to the author of this photo for posting the only sign I found acceptable and quite stunning.', '2004-08-20 02:05:39.000000', NULL, 1),
(868276, 98345, 25468, '<td valign="top">Yes! Thanks to the author for this photo. This is one of those photos that makes drudging through countless bad photos worth while.</td>', 'Yes! Thanks to the author for this photo. This is one of those photos that makes drudging through countless bad photos worth while.', '2004-08-20 02:08:24.000000', NULL, 1),
(868277, 98447, 25468, '<td valign="top">Truely fantastic. Made me laugh pretty hard. Good work.</td>', 'Truely fantastic. Made me laugh pretty hard. Good work.', '2004-08-20 02:09:24.000000', NULL, 1),
(868278, 98430, 8054, '<td valign="top">Great idea and overall great photo. I would have cropped the bottom a bit tighter as the red mist is a very dominant aspect and distracts the eye from the colored spotlights.</td>', 'Great idea and overall great photo. I would have cropped the bottom a bit tighter as the red mist is a very dominant aspect and distracts the eye from the colored spotlights.', '2004-08-20 02:09:29.000000', NULL, 1),
