INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(869594, 98474, 20779, '<td valign="top">The mood and nostalgic feel are retained beautifully. The detail is great. There are some great color contrasts, aslo.</td>', 'The mood and nostalgic feel are retained beautifully. The detail is great. There are some great color contrasts, aslo.', '2004-08-21 16:37:34.000000', NULL, 1),
(869596, 98502, 20779, '<td valign="top">You managed to attain a great depth and impact with this image. Beautifully and perfectly done. I am bumping this even higher now that I see it again!</td>', 'You managed to attain a great depth and impact with this image. Beautifully and perfectly done. I am bumping this even higher now that I see it again!', '2004-08-21 16:38:43.000000', NULL, 1),
(869597, 97560, 20779, '<td valign="top">One of the few "neon signs" in this challenge that I really thought was worthy of being the subject of the image. Great capture! Your composition is perfect and the clarity superb.</td>', 'One of the few "neon signs" in this challenge that I really thought was worthy of being the subject of the image. Great capture! Your composition is perfect and the clarity superb.', '2004-08-21 16:40:11.000000', NULL, 1),
(869598, 97779, 20779, '<td valign="top">The angle and persepctive really make this shot work.</td>', 'The angle and persepctive really make this shot work.', '2004-08-21 16:40:56.000000', NULL, 1),
(869599, 98387, 20779, '<td valign="top">The simplicity and impact of this shot is phenomenal.</td>', 'The simplicity and impact of this shot is phenomenal.', '2004-08-21 16:41:53.000000', NULL, 1),
(869601, 98386, 20779, '<td valign="top">Very nice neon blues and violets. The whites are too exposed for my personal taste, and what appears to be post processing grain. I really like the electric blue of the veins.</td>', 'Very nice neon blues and violets. The whites are too exposed for my personal taste, and what appears to be post processing grain. I really like the electric blue of the veins.', '2004-08-21 16:48:08.000000', NULL, 1),
(869602, 98456, 20779, '<td valign="top">Very nice composition. The shot would really pop with a touch more crispness in my opinion.</td>', 'Very nice composition. The shot would really pop with a touch more crispness in my opinion.', '2004-08-21 16:49:29.000000', NULL, 1),
(869603, 98524, 20779, '<td valign="top">Clever find of "neon". The composition and lighting are somewhat weak for me.</td>', 'Clever find of "neon". The composition and lighting are somewhat weak for me.', '2004-08-21 16:50:27.000000', NULL, 1),
