(870666, 98293, 12733, '<td valign="top">The colors seem to shimmer, they are so bright. Very nice.</td>', 'The colors seem to shimmer, they are so bright. Very nice.', '2004-08-22 22:55:22.000000', NULL, 1),
(870668, 97195, 12733, '<td valign="top">Very nice reflections. I think somewhat less black around the main image would make it stronger - possibly cropped down to a square.</td>', 'Very nice reflections. I think somewhat less black around the main image would make it stronger - possibly cropped down to a square.', '2004-08-22 22:56:29.000000', NULL, 1),
