(871598, 97135, 24911, '<td valign="top">Loved it. Good neon effect. Nice colors. Interesting subject. 10.</td>', 'Loved it. Good neon effect. Nice colors. Interesting subject. 10.', '2004-08-23 10:51:22.000000', NULL, 1),
(871617, 98383, 24911, '<td valign="top">Loved it. A great neon effect. loved the colors. Have no idea what it is, and don''t care. 10.</td>', 'Loved it. A great neon effect. loved the colors. Have no idea what it is, and don''t care. 10.', '2004-08-23 11:00:35.000000', NULL, 1),
(871621, 98430, 24911, '<td valign="top">Fantastic shot. Great colors. Interesting subject. 10.</td>', 'Fantastic shot. Great colors. Interesting subject. 10.', '2004-08-23 11:01:33.000000', NULL, 1),
(871719, 98516, 25553, '<td valign="top">this brings back memories.. i used to live in st louis.  ive seen the neon in motion and get the point of the pic. i like the burnt white budweiser letters.. the pic is not completely straight and it throws me off a little. good job getting the wings flapping though</td>', 'this brings back memories.. i used to live in st louis.  ive seen the neon in motion and get the point of the pic. i like the burnt white budweiser letters.. the pic is not completely straight and it throws me off a little. good job getting the wings flapping though', '2004-08-23 11:42:31.000000', NULL, 1),
(871726, 98076, 25553, '<td valign="top">incredible picture! really love it. dont see a neon though or is it the halo around the moon?</td>', 'incredible picture! really love it. dont see a neon though or is it the halo around the moon?', '2004-08-23 11:45:09.000000', NULL, 1),
