(871924, 98387, 25863, '<td valign="top">Would have been better with stars in the background, but the spinning gold center on the black background is impressive</td>', 'Would have been better with stars in the background, but the spinning gold center on the black background is impressive', '2004-08-23 13:57:26.000000', NULL, 1),
(871927, 97038, 25863, '<td valign="top">Great idea, however the camera could not handle it. Too grainy</td>', 'Great idea, however the camera could not handle it. Too grainy', '2004-08-23 13:58:27.000000', NULL, 1),
(871953, 97408, 25863, '<td valign="top">Great neon colour, but could be any jumble of neon coloured shapes. In short, the context is confusing.  Is the cafe sign in the reflection of a window? In a mirror outside reflecting the cafe sign back to photographer, who is in the cafe? A cafe built underground with a subway-like entrance a mysterious inverted sign?</td>', 'Great neon colour, but could be any jumble of neon coloured shapes. In short, the context is confusing.  Is the cafe sign in the reflection of a window? In a mirror outside reflecting the cafe sign back to photographer, who is in the cafe? A cafe built underground with a subway-like entrance a mysterious inverted sign?', '2004-08-23 14:11:57.000000', NULL, 1),
(871962, 98243, 25863, '<td valign="top">Symetric, superhero neon purple and green, but who''s work? Great work of technical know-how. Other than that, yawn.  Emotionally vapid.</td>', 'Symetric, superhero neon purple and green, but who''s work? Great work of technical know-how. Other than that, yawn.  Emotionally vapid.', '2004-08-23 14:15:33.000000', NULL, 1),
(871964, 98484, 25863, '<td valign="top">Well-centered, crisp, clear neon in black void?</td>', 'Well-centered, crisp, clear neon in black void?', '2004-08-23 14:17:20.000000', NULL, 1),
(871966, 98326, 25863, '<td valign="top">Well-centered, clear, crisp neon with a nice Surgeon General''s warning touch.</td>', 'Well-centered, clear, crisp neon with a nice Surgeon General''s warning touch.', '2004-08-23 14:18:56.000000', NULL, 1),
(871971, 98506, 25090, '<td valign="top">Just fantastic!</td>', 'Just fantastic!', '2004-08-23 14:20:34.000000', NULL, 1),
(871972, 98224, 25863, '<td valign="top">A bit too abstract. Neon does not equal light.<br/></td>', 'A bit too abstract. Neon does not equal light.', '2004-08-23 14:20:34.000000', NULL, 1),
(871976, 98512, 25863, '<td valign="top">interesting</td>', 'interesting', '2004-08-23 14:22:02.000000', NULL, 1),
(871977, 98432, 25863, '<td valign="top">Lotsa neon, but a bit fuzzy in places. A bit confused as to what i am looking at.</td>', 'Lotsa neon, but a bit fuzzy in places. A bit confused as to what i am looking at.', '2004-08-23 14:23:52.000000', NULL, 1),
(871981, 97959, 25863, '<td valign="top">Impressive conceptually, nice neon coordination presumably not setup, crisp, clear, exactly what you would see when buying some cotton candy.</td>', 'Impressive conceptually, nice neon coordination presumably not setup, crisp, clear, exactly what you would see when buying some cotton candy.', '2004-08-23 14:27:30.000000', NULL, 1),
(871997, 98060, 25863, '<td valign="top">Crisp, clear, interesting positioning, but lacks universal recognition, mostly because we dont know if it is a bar, restaurant, etc. Could be a strip joint, for all we know.</td>', 'Crisp, clear, interesting positioning, but lacks universal recognition, mostly because we dont know if it is a bar, restaurant, etc. Could be a strip joint, for all we know.', '2004-08-23 14:33:29.000000', NULL, 1),
(872001, 98517, 25863, '<td valign="top">Interesting technical feat.</td>', 'Interesting technical feat.', '2004-08-23 14:34:52.000000', NULL, 1),
(872003, 98288, 25863, '<td valign="top">Hippie.</td>', 'Hippie.', '2004-08-23 14:35:45.000000', NULL, 1),
(872008, 98489, 25863, '<td valign="top">Er, great conceptually, but the highlighter you used is not technically neon, it is dirty yellow.</td>', 'Er, great conceptually, but the highlighter you used is not technically neon, it is dirty yellow.', '2004-08-23 14:37:21.000000', NULL, 1),
(872012, 97755, 25863, '<td valign="top">Interesting neon, clear, crisp, with a bit of added context.</td>', 'Interesting neon, clear, crisp, with a bit of added context.', '2004-08-23 14:39:27.000000', NULL, 1),
(872018, 97653, 25863, '<td valign="top">Interesting concept: that green grass, when viewed closeup with bright sunshine shining through it, looks neon. Bad background. Could have been more summery or interesting: BBQ, baby, bug, kitty cat.</td>', 'Interesting concept: that green grass, when viewed closeup with bright sunshine shining through it, looks neon. Bad background. Could have been more summery or interesting: BBQ, baby, bug, kitty cat.', '2004-08-23 14:42:18.000000', NULL, 1),
(872023, 97407, 25863, '<td valign="top">Best of the neon sign category yet. A bit fuzzy however.</td>', 'Best of the neon sign category yet. A bit fuzzy however.', '2004-08-23 14:44:34.000000', NULL, 1),
(872025, 97568, 25863, '<td valign="top">Right conept, but unfocused words do not make any sense.</td>', 'Right conept, but unfocused words do not make any sense.', '2004-08-23 14:45:25.000000', NULL, 1),
