(875059, 97954, 22734, '<td valign="top">cool and breathtaking.</td>', 'cool and breathtaking.', '2004-08-24 22:16:51.000000', NULL, 1),
(875065, 98511, 23394, '<td valign="top">this shot has a lot of potential.  i love the idea and will score you on the effort.  if you don''t mind, let me take a moment to pick this a part.  the composition is fine.  the dof is too short and the focus is too soft.  the surface and background should be smooth.  you want people to be impacted by the image, not distracted by unnecessary details.  it was good to use a side light, but it was a little too strong (hence the hotspots and the shadows).  all the same, this is a great effort for a tough challenge!</td>', 'this shot has a lot of potential.  i love the idea and will score you on the effort.  if you don''t mind, let me take a moment to pick this a part.  the composition is fine.  the dof is too short and the focus is too soft.  the surface and background should be smooth.  you want people to be impacted by the image, not distracted by unnecessary details.  it was good to use a side light, but it was a little too strong (hence the hotspots and the shadows).  all the same, this is a great effort for a tough challenge!', '2004-08-24 22:21:00.000000', NULL, 1),
(875067, 98318, 23394, '<td valign="top">wild!  killer colors, great effort.  i''ll give you points for ingenuity!</td>', 'wild!  killer colors, great effort.  i''ll give you points for ingenuity!', '2004-08-24 22:22:36.000000', NULL, 1),
