(875432, 97669, 14448, '<td valign="top">Technical 2.5/3 - nice colours and tonal range, but seems oversharpened with noticeable halos<br/>Creative 2.5/3 - love the subject, restricted palette, and thoughtful composition; might like to see the subject a little lower in the frame<br/>Meets competition 3/3 - after so many godforsaken bar signs, this is a breath of fresh air in more ways than one<br/>Emotional 1/1 - I like the peaceful feeling it projects<br/> <br/>One of my favourites of the competition 9/10</td>', 'Technical 2.5/3 - nice colours and tonal range, but seems oversharpened with noticeable halosCreative 2.5/3 - love the subject, restricted palette, and thoughtful composition; might like to see the subject a little lower in the frameMeets competition 3/3 - after so many godforsaken bar signs, this is a breath of fresh air in more ways than oneEmotional 1/1 - I like the peaceful feeling it projects One of my favourites of the competition 9/10', '2004-08-25 00:49:09.000000', NULL, 1),
(875434, 97959, 22655, '<td valign="top">Creative!</td>', 'Creative!', '2004-08-25 00:49:30.000000', NULL, 1),
(875437, 97408, 18552, '<td valign="top">Very nice. I like the way you took a picture of the reflection of the sign in the mirror - makes it more interesting than just a sign.</td>', 'Very nice. I like the way you took a picture of the reflection of the sign in the mirror - makes it more interesting than just a sign.', '2004-08-25 00:50:53.000000', NULL, 1),
(875438, 98327, 23929, '<td valign="top">I love the border. Can you PM and let me know how you did that with the different colours. THANKS.</td>', 'I love the border. Can you PM and let me know how you did that with the different colours. THANKS.', '2004-08-25 00:50:58.000000', NULL, 1),
(875442, 97737, 18552, '<td valign="top">Your sign picture is really good. It sets a mood which a lot of the sign pics don''t do. The composition, color and focus are just right for this.</td>', 'Your sign picture is really good. It sets a mood which a lot of the sign pics don''t do. The composition, color and focus are just right for this.', '2004-08-25 00:52:19.000000', NULL, 1),
